syntax:
inserter(container, iterator_position) // returns an iterator that inserts elements at the specified position in the container
// 'front_inserter' inserts at the beginning, 'back_inserter' at the end
// Usage: *it = value; // inserts 'value' at the position indicated by 'it'

code_example:
struct ListNode {
    int data;
    struct ListNode *next;
};

typedef struct {
    struct ListNode *head;
} List;

/* Function to create an inserter that inserts at the front of the list */
struct ListNode* front_inserter(List *list) {
    return &(struct ListNode){.next = list->head}; // dummy node for insertion point
}

/* Function to insert a new node at the front using the inserter */
void insert_front(List *list, int value) {
    struct ListNode *new_node = malloc(sizeof(struct ListNode));
    new_node->data = value;
    new_node->next = list->head;
    list->head = new_node;
}

/* Usage example demonstrating advanced insertion techniques */
int main() {
    List my_list = {NULL};
    insert_front(&my_list, 10);
    insert_front(&my_list, 20);
    // Using custom inserter pattern to insert multiple elements at front
    struct ListNode *it = front_inserter(&my_list);
    insert_front(&my_list, 30);
    insert_front(&my_list, 40);
    // The list now contains 40 -> 30 -> 20 -> 10
    return 0;
}
